                .get("error")
                .and_then(|v| v.as_str())
                .or_else(|| val.get("status").and_then(|v| v.as_str()))
                .unwrap_or("Unknown Incus API error");
            Err(anyhow::anyhow!("Incus API error: {}", err))
        }
    }

