}

fn default_auto_load() -> Vec<String> {
    let wg_only = std::env::var("OP_DBUS_WG_ONLY")
        .ok()
        .map(|v| {
            let l = v.to_lowercase();
            !(l == "0" || l == "false" || l == "no")
        })
        .unwrap_or(false);

    if wg_only {
        return vec![
            "zeroclaw".to_string(),
            "config".to_string(),
            "service".to_string(),
            "s6".to_string(),
            "net".to_string(),
            "rtnetlink".to_string(),
            "procfs".to_string(),
            "wireguard".to_string(),
            "agent_config".to_string(),
        ];
    }

    vec![
        "mcp".to_string(),
        "zeroclaw".to_string(),
        "cognitive_mcp".to_string(),
        "compact_mcp".to_string(),
        "config".to_string(),
        "s6".to_string(),
        "incus".to_string(),
        "mail_server".to_string(),
        "unix_socket".to_string(),
        "wgcf".to_string(),
        "xray".to_string(),
        "net".to_string(),
        "openflow".to_string(),
        "ovsdb_bridge".to_string(),
        "ovsdb_daemon".to_string(),
        "rovs_commands".to_string(),
        "procfs".to_string(),
        "rtnetlink".to_string(),
