            if let Some(devices) = config.get("devices") {
                if let Ok(dev_map) = simd_json::serde::from_owned_value::<
                    HashMap<String, HashMap<String, String>>,
                >(devices.clone())
                {
                    state.devices = Some(dev_map);
                }
            }
        }

        Ok(simd_json::serde::to_owned_value(state)?)
    }

